import itertools
import json

def solve_puzzle():
    houses = [0, 1, 2, 3]  # indices for houses 1..4

    Names = ["Eric", "Peter", "Arnold", "Alice"]
    Smoothies = ["dragonfruit", "cherry", "desert", "watermelon"]
    Cigars = ["blue master", "pall mall", "dunhill", "prince"]
    Heights = ["tall", "average", "short", "very short"]
    Phones = ["google pixel 6", "samsung galaxy s21", "iphone 13", "oneplus 9"]

    solution = None

    for names in itertools.permutations(Names):
        # 11. Peter is not in the third house. (index 2 is house 3)
        if names[2] == "Peter":
            continue

        for smoothies in itertools.permutations(Smoothies):
            # 1. Dragonfruit smoothie lover is Eric.
            if smoothies.index("dragonfruit") != names.index("Eric"):
                continue
            # 5. Watermelon right of Desert
            if smoothies.index("watermelon") <= smoothies.index("desert"):
                continue

            for cigars in itertools.permutations(Cigars):
                # 9. Blue Master not in first house (index 0)
                if cigars[0] == "blue master":
                    continue
                # 13. Dragonfruit smoothie lover is partial to Pall Mall (and is Eric)
                if cigars.index("pall mall") != smoothies.index("dragonfruit"):
                    continue
                # 2. Dunhill smoker likes Cherry smoothies
                if cigars.index("dunhill") != smoothies.index("cherry"):
                    continue

                for heights in itertools.permutations(Heights):
                    # 7. Tall is in the third house
                    if heights[2] != "tall":
                        continue
                    # 10. Dunhill smoker is short
                    if heights.index("short") != cigars.index("dunhill"):
                        continue
                    # 4. Dunhill to the right of very short
                    if cigars.index("dunhill") <= heights.index("very short"):
                        continue

                    for phones in itertools.permutations(Phones):
                        # 3. S21 directly left of iPhone 13
                        if phones.index("samsung galaxy s21") + 1 != phones.index("iphone 13"):
                            continue
                        # 8. Very short uses iPhone 13
                        if phones.index("iphone 13") != heights.index("very short"):
                            continue
                        # 6. Prince smoker uses OnePlus 9
                        if phones.index("oneplus 9") != cigars.index("prince"):
                            continue
                        # 12. Arnold uses Google Pixel 6
                        if phones.index("google pixel 6") != names.index("Arnold"):
                            continue

                        # All constraints satisfied
                        solution = {
                            "header": ["House", "Name", "Smoothie", "Cigar", "Height", "PhoneModel"],
                            "rows": []
                        }
                        for i in range(4):
                            solution["rows"].append([
                                str(i + 1),
                                names[i],
                                smoothies[i],
                                cigars[i],
                                heights[i],
                                phones[i]
                            ])
                        return {"solution": solution}

    return {"solution": {"header": ["House", "Name", "Smoothie", "Cigar", "Height", "PhoneModel"], "rows": []}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
